model:
rachana: 1
sutra: filing
version: 1
description: 
match: { kind: filing, priority: 10 }
title: { pill: "US equities · Filing", id: "$.ACCESSION", with: "link($.COMPANY, 'us-company', $.COMPANY_NAME)" }
strip:
  - { label: "Company", bind: "$.COMPANY", emphasis: true }
  - { label: "Form", bind: "$.FORM" }
  - { label: "What it is", bind: "$.FORM_NAME" }
  - { label: "Filed", bind: "$.FILED", fmt: "date" }
  - { label: "Report date", bind: "$.REPORT_DATE", fmt: "date" }
panels:
  - id: filing
    kind: kv
    title: "Filing"
    key: "F2"
    columns:
      - { label: "Accession", bind: "link($.ACCESSION, 'filing')" }
      - { label: "Company", bind: "link($.COMPANY, 'us-company', $.COMPANY_NAME)" }
      - { label: "Form", bind: "$.FORM" }
      - { label: "What it is", bind: "$.FORM_NAME" }
      - { label: "Filed", bind: "$.FILED", fmt: "date" }
      - { label: "Report date", bind: "$.REPORT_DATE", fmt: "date" }
      - { label: "8-K items", bind: "$.ITEMS_TEXT" }
      - { label: "Document", bind: "$.DOCUMENT_DESCRIPTION" }
      - { label: "Size (KB)", bind: "$.SIZE_KB", fmt: "amount0" }
      - { label: "Open on EDGAR", bind: "'https://www.sec.gov/Archives/edgar/data/' + $.PATH + '/' + $.PRIMARY_DOCUMENT" }
      - { label: "EDGAR filing index", bind: "'https://www.sec.gov/Archives/edgar/data/' + $.PATH + '/' + $.ACCESSION + '-index.htm'" }
  - id: items
    kind: table
    title: "Items reported (8-K)"
    rows: "$.ITEMS"
    search: false
    empty: "No items (only a current report, 8-K, lists items)"
    columns:
      - { label: "Item", bind: "@.ITEM" }
      - { label: "What it reports", bind: "@.DESCRIPTION" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F7: "link($.COMPANY, 'us-company')", F9: "raw" }
